describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow();
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 600 },
            ],
            900,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 500, costCents: 300 }, // intentionally out of order to test sorting
      { upToGrams: 2000, costCents: 800 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for cart with zero-weight products", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
      ];
      expect(calc.computeShippingCents(lines, 500)).toBe(0);
    });

    it("selects first bracket when weight <= lowest upToGrams", () => {
      // weight=400g, sorted brackets: 500/300, 1000/500, 2000/800
      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 1000)).toBe(
        300,
      );
    });

    it("selects exact bracket boundary", () => {
      // weight=500g exactly → bracket 500/300
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 1000)).toBe(
        300,
      );
    });

    it("selects next bracket above boundary", () => {
      // weight=501g → bracket 1000/500
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 1000)).toBe(
        500,
      );
    });

    it("selects highest bracket at upper boundary", () => {
      // weight=2000g → bracket 2000/800
      expect(calc.computeShippingCents([makeLine("a", 2000, 1)], 1000)).toBe(
        800,
      );
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [{ upToGrams: 1000, costCents: 500 }],
        1200,
      );
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 1500, 1)], 1000),
      ).toBe(1200);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      // weight=3000g, no overflow specified → last bracket = 2000/800
      expect(calc.computeShippingCents([makeLine("a", 3000, 1)], 1000)).toBe(
        800,
      );
    });

    it("sums weight across multiple lines", () => {
      // 2 items of 300g each = 600g total → bracket 1000/500
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(500);
    });
  });
});

