      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
    }
  });

  it("throws InventoryError for partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("succeeds when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy: mockDiscount, region: "FR" });
    cart.add(productA, 1); // subtotal=1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2), // 20%
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(200); // 20% of 1000
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("async tax is applied on discounted subtotal", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal=1000, discount=300, discountedSubtotal=700
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10%
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(70); // 10% of 700
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(400),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(productA, 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // subtotal = 1200 * 2 = 2400, discount=0, tax = 5% of 2400 = 120, shipping=400
    expect(result.totals.subtotalCents).toBe(2400);
    expect(result.totals.taxCents).toBe(120);
    expect(result.totals.shippingCents).toBe(400);
    expect(result.totals.totalCents).toBe(2400 + 120 + 400);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service error",
    );
  });

  it("inventory check uses custom reason in error message", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).message).toBe("discontinued");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [101], [NaN], [Infinity], [-Infinity]])(
      "rejects invalid percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([[0], [50], [100]])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      // 33% of 100 = 33.0 → 33
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(101)).toBe(33); // 33.33 → 33
    });

    it("100% discount returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotal correctly", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 1_000_000 = 150_000
      expect(policy.computeDiscountCents(1_000_000)).toBe(150_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(200)).toBe(200);
    });

    it("returns exact subtotal when equal to amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow();
    });

    it("accepts single policy", () => {
      expect(
        () => new CompositeDiscountPolicy([new NoDiscountPolicy()]),
      ).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // fixed 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("sum can exceed subtotal (clamping is caller responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 80% of 100 = 80
          new FixedAmountDiscountPolicy(80), // capped to 100 by FixedAmount
        ],
        "sum",
      );
      // 80 + 100 = 180, which exceeds subtotal — Cart.totals() clamps
      expect(composite.computeDiscountCents(100)).toBe(180);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ]);
      // 10% of 1000=100, fixed=50, sum=150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining = 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // bigFirst: 500 off 1000 → remaining=500, then 50% of 500=250, total=750
      expect(bigFirst.computeDiscountCents(1000)).toBe(750);
      // smallFirst: 50% of 1000=500, remaining=500, then fixed 500, total=1000
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("chain cannot exceed subtotal (capped per step)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "chain",
      );
      // 800 off 1000 → remaining=200, then min(800,200)=200, total=1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

