      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("sum can exceed subtotal (clamping is caller responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 80% of 100 = 80
          new FixedAmountDiscountPolicy(80), // capped to 100 by FixedAmount
        ],
        "sum",
      );
      // 80 + 100 = 180, which exceeds subtotal — Cart.totals() clamps
      expect(composite.computeDiscountCents(100)).toBe(180);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ]);
      // 10% of 1000=100, fixed=50, sum=150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining = 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // bigFirst: 500 off 1000 → remaining=500, then 50% of 500=250, total=750
      expect(bigFirst.computeDiscountCents(1000)).toBe(750);
      // smallFirst: 50% of 1000=500, remaining=500, then fixed 500, total=1000
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("chain cannot exceed subtotal (capped per step)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "chain",
      );
      // 800 off 1000 → remaining=200, then min(800,200)=200, total=1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
