    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("async tax is applied on discounted subtotal", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal=1000, discount=300, discountedSubtotal=700
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10%
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(70); // 10% of 700
  });

