    });
    // subtotal = 1200 * 2 = 2400, discount=0, tax = 5% of 2400 = 120, shipping=400
    expect(result.totals.subtotalCents).toBe(2400);
    expect(result.totals.taxCents).toBe(120);
    expect(result.totals.shippingCents).toBe(400);
