import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

const productA: Product = { id: "a", name: "A", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "B", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart - line management", () => {
  it("starts empty", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("add() inserts a new line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("add() merges quantity for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("remove() deletes existing product and returns true", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes line quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear() removes all lines", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal=1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(500);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount exceeding subtotal to subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(productA, 1); // subtotal=1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(productA, 1); // subtotal=1000, discount=200, discountedSubtotal=800
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
  });

  it("shipping receives lines and discounted subtotal", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(productA, 1); // subtotal=1000, discount=100, discountedSubtotal=900
    cart.totals();
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(productA, 1); // subtotal=1000
    const totals = cart.totals();
    // discountedSubtotal = 1000-100 = 900
    // total = 900 + 72 + 500 = 1472
    expect(totals.totalCents).toBe(1472);
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(100);
    expect(totals.taxCents).toBe(72);
    expect(totals.shippingCents).toBe(500);
  });

  it("clamps negative tax to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to US region when not specified", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(productA, 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("empty cart totals are all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

describe("Cart - checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1); // original price 1000
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, availableQuantity: 2 }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
    }
  });

  it("throws InventoryError for partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 3 }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("succeeds when inventory is sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const mockDiscount: DiscountPolicy = {
